    existing = self._store.get_reservation(order_id)
    if existing is not None and existing.status_at(now) in (
        ReservationStatus.ACTIVE,
        ReservationStatus.CONFIRMED,
    ):
        raise DuplicateReservationError(order_id)
    for (wh, sku), total in totals(parsed).items():
        free = self._available(wh, sku, now)
        if total > free:
            raise InsufficientStockError(wh, sku, total, free)
    record = ReservationRecord(lines=parsed, created_at=now, expires_at=now + ttl)
    self._store.put_reservation(order_id, record)
    expires = format_timestamp(record.expires_at)
    for line in parsed:
        self._log.append(
            now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku,
            qty=line.qty, expires=expires,
        )
    logger.info("reserved order %s (%d lines)", order_id, len(parsed))
    return self._snapshot(order_id, record, now)

def confirm(self, order_id: str) -> Reservation:
    """Подтверждает активный резерв: списывает физический остаток по строкам."""
    now = self._clock.now()
    record = self._find(order_id)
    self._require_active(order_id, record, now)
    for (wh, sku), total in totals(record.lines).items():
        physical = self._store.get_qty(wh, sku)
        if total > physical:
            raise InsufficientStockError(wh, sku, total, physical)
    for line in record.lines:
        current = self._store.get_qty(line.warehouse, line.sku)
        self._store.set_qty(line.warehouse, line.sku, current - line.qty)
    record.status = ReservationStatus.CONFIRMED
    for line in record.lines:
        self._log.append(
            now, "ISSUE", wh=line.warehouse, sku=line.sku, qty=line.qty, ref=order_id
        )
    self._log.append(now, "RESERVE_CONFIRM", order=order_id)
    logger.info("confirmed reservation %s", order_id)
    return self._snapshot(order_id, record, now)

def cancel(self, order_id: str) -> Reservation:
    """Отменяет резерв; повторная отмена и отмена истёкшего ничего не меняют."""
    now = self._clock.now()
    record = self._find(order_id)
    status = record.status_at(now)
    if status is ReservationStatus.CONFIRMED:
        raise ReservationStateError(order_id, status.value)
    if status is ReservationStatus.ACTIVE:
        record.status = ReservationStatus.CANCELLED
        self._log.append(now, "RESERVE_CANCEL", order=order_id)
        logger.info("cancelled reservation %s", order_id)
    return self._snapshot(order_id, record, now)

