    """Переносит срок на «сейчас + ttl», но никогда не сокращает его."""
    now = self._clock.now()
    ttl = resolve_ttl(ttl)
    record = self._find(order_id)
    self._require_active(order_id, record, now)
    new_expiry = now + ttl
